local ROOT = "HumanoidRootPart"
local PARENT = {["Torso"]="HumanoidRootPart",["Head"]="Torso",["Left Arm"]="Torso",["Right Arm"]="Torso",["Left Leg"]="Torso",["Right Leg"]="Torso",["BodyAttach"]="Right Arm",["OffHandAttach"]="Left Arm",["SheathAttach"]="Torso"}
local MARKERS = {[11]={{"Hit",""}},[15]={{"EndLag",""}}}
